-- S411 SkySotol, 2026-10-18. Rule 8 ingest through execute_sql: INSERT-only, idempotent on slug.
-- Rollback: delete from public.cpl_memory where author = 'SkySotolS411';
insert into public.cpl_memory (slug, kind, org, title, summary, detail, plain, tags, source, related, status, author)
select x.slug, x.kind, 'cpl', x.title, x.summary, x.detail, x.plain, x.tags, 'CPL-Initiative/cpl-project-tracker#2216; docs/program_requirements_harvest_lessons.md S411', '{}'::text[], x.status, 'SkySotolS411'
from jsonb_to_recordset($json$[{"slug": "catalog-sweep-s411-hartnell-code-headings-2026-10-18", "kind": "milestone", "title": "S411: Hartnell read by its Coursedog code headings; build 182e810e207d", "summary": "S411 #2216: Hartnell's PDF read by its Title - CODE headings. 8 of the 33 left out loaded (run 39090337524), 14 loaded records moved from a sibling award's page to their own (reread 39090450992), 4 wrong-page rows removed under a receipt (migrate run 39090450880). Extraction $2.05. Build 182e810e207d: 15,651 programs at 111 colleges.", "detail": "The PDF does not print 31 of Hartnell's 105 listed programs (Kinesiology, Addiction Studies, the General Studies emphases, Agriculture Production, Small Farm, CalGETC). Network and Security A.S. stays out: the catalog renumbered CIS 50-55 as CSS50-55 and COCI still lists CIS. Hartnell holds 72 rows.", "plain": "Hartnell College's program requirements now come from each program's own section of its catalog PDF, found by the program code the catalog prints beside each title.", "tags": ["program-requirements", "catalog-sweep", "coursedog", "pdf-reader"], "status": "proposed"}, {"slug": "coursedog-pdf-code-headings-2026-10-18", "kind": "fact", "title": "A Coursedog PDF heads each program Title - CODE; the reader picks by that heading", "summary": "Coursedog's whole-catalog PDF heads each program \"Title - CODE\", the prefix naming the award (Biology - AS.BIO, Sociology for Transfer (AA-T) - AAT-SOC). Where a catalog heads half its listed programs so, pdf_code_assign() gives each code to the programs it names most fully (page_winners' rule) and leaves a program no heading names unread (#2216).", "detail": "Headings may wrap onto two lines, put the code on the next line, use a hyphen (AAT-SOC), or run two into one pypdf line. Titles drop 'for transfer' before matching. LEVEL reads 'Level -1'. On Hartnell the title-and-codes picker had sent 33 programs to course-set pages and 14 more to a sibling award's page.", "plain": "Some catalogs print a short program code beside each program's name, and the reader now uses it to find each program's own pages.", "tags": ["program-requirements", "coursedog", "pdf-reader"], "status": "proposed"}, {"slug": "reconcile-files-sources-filed-from-guard-2026-10-18", "kind": "pitfall", "title": "A reconcile run's fresh sources hid moved records from the next extraction", "summary": "A reconcile run files its fresh sources.json beside records it did not move, so unchanged() kept 127 records filed from another page than their source names (Los Angeles City 69, Pierce 43, Santa Rosa 11). filed_from() keeps a record only when extracted from its source's page (#2216). Test a reader change with a capture-only read (extract=0).", "detail": "The capture-only read files capture_preview.json alone; its would_extract lists each moved program with its old and new page and replaces nothing. A later extraction read of LA City, Pierce or Santa Rosa now re-extracts those 123 records.", "plain": "A check meant to save model calls could keep an outdated record after the reader moved a program to a new page; it now checks the record's own page.", "tags": ["program-requirements", "pitfall", "reconcile"], "status": "proposed"}, {"slug": "merced-coursedog-requisites-tab-2026-10-18", "kind": "fact", "title": "Merced's Coursedog catalog: no whole-catalog PDF; each program's Requisites tab prints its list", "summary": "Merced (catalog.mccd.edu, school merced_colleague_ethos, catalogId QTM2GIg9kimBOfyC8Dbb): the vendor's pdf-reports call answers 404 and there is no sitemap. The program search names 191 programs (05000.AA, Accounting (AA)); each /programs/<code> opens on an overview tab, and its Requisites tab (/programs/05000.AA/requisites-ojrrt) prints the list with credits (S411 page reads).", "detail": "Page reads 39089955502, 39090140618, 39090305534, 39090533458. A page read may keep a vendor host's data calls by naming it in network_hosts (#2216). Each program page also offers its own PDF.", "plain": "Merced's online catalog shows each program's required courses on a separate Requisites tab, which the reader can read once taught to open it.", "tags": ["program-requirements", "catalog-sweep", "coursedog"], "status": "proposed"}, {"slug": "smartcatalog-three-level-tree-2026-10-18", "kind": "fact", "title": "SmartCatalog: index, then subject or group, then the program page", "summary": "Crafton Hills' Credit Programs lists 41 subjects (credit-programs/accounting-acct), each listing its programs under 'In this section'; Taft's Degrees and Certificates lists each program as 'Title: Award', some entries groups (Welding Technology: an A.S. and five certificates). The program page prints required courses, units and total. No sitemap (S411 page reads 39090262960, 39090533458).", "detail": "Crafton: Accounting - Associate of Arts Degree, Total Credit Hours 21.00; Teacher Certificate of Achievement 25.00. Taft: Welding Technology: A.S. 21; Structural Code Welding CoA 12. A plan never names a page another page's follow reaches: the reader skips a page it already read.", "plain": "Two colleges' catalogs keep each program's requirements two clicks below the list of subjects, which tells the reader how to walk them.", "tags": ["program-requirements", "catalog-sweep", "smartcatalog"], "status": "proposed"}]$json$::jsonb)
  as x(slug text, kind text, title text, summary text, detail text, plain text, tags text[], status text)
on conflict (slug) do nothing
returning slug;
